INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('air-fried-chicken-tenders', 'Air-Fried Chicken Tenders', 'Crunchy panko tenders that kids and grown-ups both eat. Good with honey mustard.', 'Chicken & turkey', 'Air Fry', '400°F', 'Middle', '15 min', '12–14 min', '4', '1½ lb chicken tenders
½ cup flour
1 tsp kosher salt
½ tsp black pepper
½ tsp paprika
2 eggs
1½ cups panko breadcrumbs
Cooking spray or 1 Tbsp oil
For the honey mustard:
3 Tbsp Dijon mustard
2 Tbsp honey
2 Tbsp mayonnaise', 'Set up three shallow bowls: flour mixed with the salt, pepper and paprika; the eggs, beaten; and the panko.
Dredge each tender in flour, dip in egg, then press into the panko to coat.
Lay the tenders in the air basket in one layer and spray or brush lightly with oil.
Oven: Air Fry 400°F, basket on the middle shelf, 12 to 14 minutes, turning once, until golden and 165°F inside
Stir the mustard, honey and mayonnaise together and serve on the side.', '', 'kids, air basket, weeknight', '', '', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'starter', 1, '');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Air-Fried Chicken Tenders","summary":"Crunchy panko tenders that kids and grown-ups both eat. Good with honey mustard.","category":"Chicken & turkey","mode":"Air Fry","temp":"400°F","shelf":"Middle","prep":"15 min","cook":"12–14 min","servings":"4","ingredients":"1½ lb chicken tenders\n½ cup flour\n1 tsp kosher salt\n½ tsp black pepper\n½ tsp paprika\n2 eggs\n1½ cups panko breadcrumbs\nCooking spray or 1 Tbsp oil\nFor the honey mustard:\n3 Tbsp Dijon mustard\n2 Tbsp honey\n2 Tbsp mayonnaise","steps":"Set up three shallow bowls: flour mixed with the salt, pepper and paprika; the eggs, beaten; and the panko.\nDredge each tender in flour, dip in egg, then press into the panko to coat.\nLay the tenders in the air basket in one layer and spray or brush lightly with oil.\nOven: Air Fry 400°F, basket on the middle shelf, 12 to 14 minutes, turning once, until golden and 165°F inside\nStir the mustard, honey and mayonnaise together and serve on the side.","notes":"","tags":"kids, air basket, weeknight"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'air-fried-chicken-tenders';
