INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('apple-crumble', 'Apple Crumble', 'Soft, sweet apples under a buttery oat topping.', 'Desserts & baking', 'Bake', '375°F', 'Middle', '20 min', '35–40 min', '6', 'For the filling:
5 apples (a mix of tart and sweet), peeled and sliced
2 Tbsp sugar
1 Tbsp lemon juice
1 tsp ground cinnamon
1 Tbsp flour
For the topping:
¾ cup flour
¾ cup rolled oats
½ cup brown sugar
½ tsp ground cinnamon
¼ tsp kosher salt
½ cup (1 stick) cold butter, cubed', 'Oven: preheat on Bake, 375°F, middle shelf
Toss the apples with the sugar, lemon juice, cinnamon and flour, and spread them in an 8×8 baking dish.
For the topping, mix the flour, oats, brown sugar, cinnamon and salt, then rub in the butter with your fingers until it forms clumps.
Scatter the topping over the apples.
Oven: Bake 35 to 40 minutes, until golden and bubbling at the edges
Let it sit 10 minutes. Good with vanilla ice cream.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'fall, dessert', 'https://juneoven.com/pages/recipe-apple-crumble-e68732f6', 'https://recipe-media.juneoven.com/recipes-prod/rec_e68732f6-ab0d-48a8-aa67-852d7d894bac.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Apple Crumble","summary":"Soft, sweet apples under a buttery oat topping.","category":"Desserts & baking","mode":"Bake","temp":"375°F","shelf":"Middle","prep":"20 min","cook":"35–40 min","servings":"6","ingredients":"For the filling:\n5 apples (a mix of tart and sweet), peeled and sliced\n2 Tbsp sugar\n1 Tbsp lemon juice\n1 tsp ground cinnamon\n1 Tbsp flour\nFor the topping:\n¾ cup flour\n¾ cup rolled oats\n½ cup brown sugar\n½ tsp ground cinnamon\n¼ tsp kosher salt\n½ cup (1 stick) cold butter, cubed","steps":"Oven: preheat on Bake, 375°F, middle shelf\nToss the apples with the sugar, lemon juice, cinnamon and flour, and spread them in an 8×8 baking dish.\nFor the topping, mix the flour, oats, brown sugar, cinnamon and salt, then rub in the butter with your fingers until it forms clumps.\nScatter the topping over the apples.\nOven: Bake 35 to 40 minutes, until golden and bubbling at the edges\nLet it sit 10 minutes. Good with vanilla ice cream.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"fall, dessert"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'apple-crumble';
