INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('bacon', 'Bacon', 'Flat, evenly crisp bacon without standing at the stove.', 'Breakfast', 'Bake', '400°F', 'Middle', '2 min', '14–20 min', '4', '8–12 slices bacon', 'Line the June pan with foil and lay the bacon on it in one layer. Slices can touch but shouldn''t overlap.
Oven: Bake 400°F, middle shelf, no preheat needed
Cook 14 to 20 minutes, until as crisp as you like. Thick-cut takes longer.
Move the bacon to paper towels to drain. Let the fat cool before throwing away the foil.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'quick, basics, popular', 'https://juneoven.com/pages/recipe-bacon-c64adc5f', 'https://recipe-media.juneoven.com/recipes-prod/rec_c64adc5f-cead-44af-9a1d-d61f3e1faa20.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Bacon","summary":"Flat, evenly crisp bacon without standing at the stove.","category":"Breakfast","mode":"Bake","temp":"400°F","shelf":"Middle","prep":"2 min","cook":"14–20 min","servings":"4","ingredients":"8–12 slices bacon","steps":"Line the June pan with foil and lay the bacon on it in one layer. Slices can touch but shouldn''t overlap.\nOven: Bake 400°F, middle shelf, no preheat needed\nCook 14 to 20 minutes, until as crisp as you like. Thick-cut takes longer.\nMove the bacon to paper towels to drain. Let the fat cool before throwing away the foil.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"quick, basics, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'bacon';
