INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('banana-bread', 'Banana Bread', 'The classic loaf for very ripe bananas.', 'Desserts & baking', 'Bake', '350°F', 'Bottom', '15 min', '55–65 min', '1 loaf', '3 very ripe bananas
⅓ cup butter, melted
¾ cup brown sugar
1 egg, beaten
1 tsp vanilla extract
1 tsp baking soda
¼ tsp kosher salt
1½ cups flour
½ cup chopped walnuts or chocolate chips (optional)', 'Oven: preheat on Bake, 350°F, bottom shelf
Grease a 9×5 or 8×4 loaf pan.
Mash the bananas in a big bowl. Stir in the melted butter, then the sugar, egg and vanilla.
Sprinkle the baking soda and salt over, stir, then fold in the flour until no dry streaks remain. Fold in the nuts or chips.
Scrape into the pan.
Oven: Bake 55 to 65 minutes, until a skewer in the center comes out clean. If the top browns too fast, lay a piece of foil over it for the last 15 minutes.
Cool in the pan for 10 minutes, then turn out onto a rack.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'one bowl, breakfast, make ahead', 'https://juneoven.com/pages/recipe-banana-bread-5c06fa4d', 'https://recipe-media.juneoven.com/recipes-prod/rec_5c06fa4d-0373-4731-893d-6708b33f7eb9.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Banana Bread","summary":"The classic loaf for very ripe bananas.","category":"Desserts & baking","mode":"Bake","temp":"350°F","shelf":"Bottom","prep":"15 min","cook":"55–65 min","servings":"1 loaf","ingredients":"3 very ripe bananas\n⅓ cup butter, melted\n¾ cup brown sugar\n1 egg, beaten\n1 tsp vanilla extract\n1 tsp baking soda\n¼ tsp kosher salt\n1½ cups flour\n½ cup chopped walnuts or chocolate chips (optional)","steps":"Oven: preheat on Bake, 350°F, bottom shelf\nGrease a 9×5 or 8×4 loaf pan.\nMash the bananas in a big bowl. Stir in the melted butter, then the sugar, egg and vanilla.\nSprinkle the baking soda and salt over, stir, then fold in the flour until no dry streaks remain. Fold in the nuts or chips.\nScrape into the pan.\nOven: Bake 55 to 65 minutes, until a skewer in the center comes out clean. If the top browns too fast, lay a piece of foil over it for the last 15 minutes.\nCool in the pan for 10 minutes, then turn out onto a rack.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"one bowl, breakfast, make ahead"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'banana-bread';
