INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('beef-jerky', 'Beef Jerky', 'Homemade jerky with a soy, garlic and pepper marinade.', 'Snacks & dips', 'Dehydrate', '160°F', 'Middle', '20 min + overnight marinating', '4–6 hr', 'About ½ lb jerky', '1½ lb lean beef (eye of round or top round), trimmed of fat
½ cup soy sauce
2 Tbsp Worcestershire sauce
1 Tbsp brown sugar
1 tsp garlic powder
1 tsp onion powder
1 tsp black pepper
½ tsp red pepper flakes (optional)', 'Freeze the beef for 1 hour so it''s easy to slice, then cut it against the grain into ¼-inch strips.
Mix everything else in a bowl or bag, add the beef and marinate in the fridge overnight.
Drain the strips and pat them dry. Lay them flat in the air basket without touching.
Oven: Dehydrate 160°F, 4 to 6 hours, until dry and leathery but still bendy
Oven: for safety, finish on Bake, 275°F, for 10 minutes so the meat is sure to reach 160°F
Cool completely and store airtight in the fridge.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'dehydrate, snack, make ahead', 'https://juneoven.com/pages/recipe-beef-jerky-71d33843', 'https://recipe-media.juneoven.com/recipes-prod/rec_71d33843-9053-41f0-a38b-5a77d3003161.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Beef Jerky","summary":"Homemade jerky with a soy, garlic and pepper marinade.","category":"Snacks & dips","mode":"Dehydrate","temp":"160°F","shelf":"Middle","prep":"20 min + overnight marinating","cook":"4–6 hr","servings":"About ½ lb jerky","ingredients":"1½ lb lean beef (eye of round or top round), trimmed of fat\n½ cup soy sauce\n2 Tbsp Worcestershire sauce\n1 Tbsp brown sugar\n1 tsp garlic powder\n1 tsp onion powder\n1 tsp black pepper\n½ tsp red pepper flakes (optional)","steps":"Freeze the beef for 1 hour so it''s easy to slice, then cut it against the grain into ¼-inch strips.\nMix everything else in a bowl or bag, add the beef and marinate in the fridge overnight.\nDrain the strips and pat them dry. Lay them flat in the air basket without touching.\nOven: Dehydrate 160°F, 4 to 6 hours, until dry and leathery but still bendy\nOven: for safety, finish on Bake, 275°F, for 10 minutes so the meat is sure to reach 160°F\nCool completely and store airtight in the fridge.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"dehydrate, snack, make ahead"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'beef-jerky';
