INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('chili-lime-crispy-chickpeas', 'Chili-Lime Crispy Chickpeas', 'A crunchy, salty snack from a can of chickpeas.', 'Snacks & dips', 'Air Fry', '400°F', 'Middle', '5 min', '15–20 min', '2–4', '1 can (15 oz) chickpeas, drained, rinsed and dried very well
1 Tbsp olive oil
1 tsp chili powder
½ tsp kosher salt
Zest of 1 lime', 'Toss the chickpeas with the oil.
Spread them in the air basket in one layer.
Oven: Air Fry 400°F, basket on the middle shelf, 15 to 20 minutes, shaking every 5 minutes, until crunchy
Toss right away with the chili powder, salt and lime zest. They crisp more as they cool.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'snack, vegan, air basket', 'https://juneoven.com/pages/recipe-chili-lime-crispy-chickpeas-79d3b869', 'https://recipe-media.juneoven.com/recipes-prod/rec_79d3b869-bc56-44a4-80ae-bfcd0bc6947e.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Chili-Lime Crispy Chickpeas","summary":"A crunchy, salty snack from a can of chickpeas.","category":"Snacks & dips","mode":"Air Fry","temp":"400°F","shelf":"Middle","prep":"5 min","cook":"15–20 min","servings":"2–4","ingredients":"1 can (15 oz) chickpeas, drained, rinsed and dried very well\n1 Tbsp olive oil\n1 tsp chili powder\n½ tsp kosher salt\nZest of 1 lime","steps":"Toss the chickpeas with the oil.\nSpread them in the air basket in one layer.\nOven: Air Fry 400°F, basket on the middle shelf, 15 to 20 minutes, shaking every 5 minutes, until crunchy\nToss right away with the chili powder, salt and lime zest. They crisp more as they cool.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"snack, vegan, air basket"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'chili-lime-crispy-chickpeas';
