INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('chocolate-chip-cookies', 'Chocolate Chip Cookies', 'Chewy in the middle, crisp at the edges. Bake a few at a time and keep the dough in the fridge.', 'Desserts & baking', 'Bake', '350°F', 'Middle', '15 min', '11–13 min per batch', 'About 24 cookies', '2¼ cups (280 g) flour
1 tsp baking soda
1 tsp kosher salt
1 cup (2 sticks) butter, softened
¾ cup brown sugar, packed
½ cup sugar
2 eggs
2 tsp vanilla extract
2 cups chocolate chips', 'Whisk the flour, baking soda and salt in a bowl.
In a big bowl, beat the butter and both sugars until light and fluffy, about 3 minutes. Beat in the eggs one at a time, then the vanilla.
Stir in the flour mixture until just combined, then the chocolate chips.
Chill the dough for at least 30 minutes, or up to 3 days.
Oven: preheat on Bake, 350°F, middle shelf
Scoop 2-tablespoon balls onto the parchment-lined June pan, about 2 inches apart; 8 to 10 fit.
Oven: Bake 11 to 13 minutes, until golden at the edges and still soft in the center
Cool on the pan for 5 minutes, then move to a rack. Repeat with the rest of the dough.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'cookies, make ahead, kids', 'https://juneoven.com/pages/recipe-chocolate-chip-cookies-ab55bf02', 'https://recipe-media.juneoven.com/recipes-prod/rec_ab55bf02-4f6d-4d71-9361-3e90661832e1.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Chocolate Chip Cookies","summary":"Chewy in the middle, crisp at the edges. Bake a few at a time and keep the dough in the fridge.","category":"Desserts & baking","mode":"Bake","temp":"350°F","shelf":"Middle","prep":"15 min","cook":"11–13 min per batch","servings":"About 24 cookies","ingredients":"2¼ cups (280 g) flour\n1 tsp baking soda\n1 tsp kosher salt\n1 cup (2 sticks) butter, softened\n¾ cup brown sugar, packed\n½ cup sugar\n2 eggs\n2 tsp vanilla extract\n2 cups chocolate chips","steps":"Whisk the flour, baking soda and salt in a bowl.\nIn a big bowl, beat the butter and both sugars until light and fluffy, about 3 minutes. Beat in the eggs one at a time, then the vanilla.\nStir in the flour mixture until just combined, then the chocolate chips.\nChill the dough for at least 30 minutes, or up to 3 days.\nOven: preheat on Bake, 350°F, middle shelf\nScoop 2-tablespoon balls onto the parchment-lined June pan, about 2 inches apart; 8 to 10 fit.\nOven: Bake 11 to 13 minutes, until golden at the edges and still soft in the center\nCool on the pan for 5 minutes, then move to a rack. Repeat with the rest of the dough.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"cookies, make ahead, kids"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'chocolate-chip-cookies';
