INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('cinnamon-toast', 'Cinnamon Toast', 'Crisp, sugary cinnamon toast, the way the broiler does it best.', 'Breakfast', 'Broil', 'High', 'Top', '3 min', '3–5 min', '2', '4 slices bread
3 Tbsp butter, softened
3 Tbsp sugar
1½ tsp ground cinnamon
Pinch of salt', 'Mix the butter, sugar, cinnamon and salt into a paste.
Spread it right to the edges of each slice and set the slices on the June pan.
Oven: Broil on high, top shelf, 3 to 5 minutes, until bubbling and caramelized. Watch it closely; it goes from golden to dark fast.
Let it cool for a minute so the sugar crisps.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'quick, kids', 'https://juneoven.com/pages/recipe-cinnamon-toast-4d462da6', 'https://recipe-media.juneoven.com/recipes-prod/rec_4d462da6-53af-4121-a4d5-3a274a9511a3.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Cinnamon Toast","summary":"Crisp, sugary cinnamon toast, the way the broiler does it best.","category":"Breakfast","mode":"Broil","temp":"High","shelf":"Top","prep":"3 min","cook":"3–5 min","servings":"2","ingredients":"4 slices bread\n3 Tbsp butter, softened\n3 Tbsp sugar\n1½ tsp ground cinnamon\nPinch of salt","steps":"Mix the butter, sugar, cinnamon and salt into a paste.\nSpread it right to the edges of each slice and set the slices on the June pan.\nOven: Broil on high, top shelf, 3 to 5 minutes, until bubbling and caramelized. Watch it closely; it goes from golden to dark fast.\nLet it cool for a minute so the sugar crisps.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"quick, kids"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'cinnamon-toast';
