INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('dinner-rolls', 'Dinner Rolls', 'Soft pull-apart rolls, risen in the oven on Proof.', 'Bread, pizza & sandwiches', 'Bake', '375°F', 'Middle', '25 min + 1 hr 30 min rising', '15–18 min', '12 rolls', '3½ cups (440 g) flour
2¼ tsp instant yeast (1 packet)
3 Tbsp sugar
1½ tsp kosher salt
1 cup warm milk
1 egg
4 Tbsp butter, melted, plus more for brushing', 'Mix the flour, yeast, sugar and salt. Add the milk, egg and butter and knead (by hand or with a mixer) for about 8 minutes, until smooth and springy.
Put the dough in a greased bowl and cover.
Oven: Proof about 1 hour, until doubled
Divide into 12 pieces, roll each into a tight ball and set them in a greased 9×9 pan or on the June pan, just touching.
Oven: Proof 30 minutes more, until puffy
Take the pan out of the oven.
Oven: preheat on Bake, 375°F, middle shelf
Oven: Bake 15 to 18 minutes, until golden
Brush the warm rolls with melted butter.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'bread, proof, holiday', 'https://juneoven.com/pages/recipe-dinner-rolls-bc95b2dc', 'https://recipe-media.juneoven.com/recipes-prod/rec_bc95b2dc-c878-4849-b9db-c87d61927181.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Dinner Rolls","summary":"Soft pull-apart rolls, risen in the oven on Proof.","category":"Bread, pizza & sandwiches","mode":"Bake","temp":"375°F","shelf":"Middle","prep":"25 min + 1 hr 30 min rising","cook":"15–18 min","servings":"12 rolls","ingredients":"3½ cups (440 g) flour\n2¼ tsp instant yeast (1 packet)\n3 Tbsp sugar\n1½ tsp kosher salt\n1 cup warm milk\n1 egg\n4 Tbsp butter, melted, plus more for brushing","steps":"Mix the flour, yeast, sugar and salt. Add the milk, egg and butter and knead (by hand or with a mixer) for about 8 minutes, until smooth and springy.\nPut the dough in a greased bowl and cover.\nOven: Proof about 1 hour, until doubled\nDivide into 12 pieces, roll each into a tight ball and set them in a greased 9×9 pan or on the June pan, just touching.\nOven: Proof 30 minutes more, until puffy\nTake the pan out of the oven.\nOven: preheat on Bake, 375°F, middle shelf\nOven: Bake 15 to 18 minutes, until golden\nBrush the warm rolls with melted butter.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"bread, proof, holiday"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'dinner-rolls';
