INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Double Chocolate Peanut Butter Cookies","summary":"","category":"Desserts & baking","mode":"","temp":"","shelf":"","prep":"","cook":"","servings":"","ingredients":"","steps":"","notes":"","tags":""}', 'Project July', 'Page for a recipe from June''s library', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'double-chocolate-peanut-butter-cookies';
INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('dried-apple-rings', 'Dried Apple Rings', 'Chewy dried apple rings with the Dehydrate mode.', 'Snacks & dips', 'Dehydrate', '135°F', 'Middle', '15 min', '6–8 hr', 'About 40 rings', '3 apples
1 cup water mixed with 2 Tbsp lemon juice
Ground cinnamon (optional)', 'Core the apples and slice them crosswise into ⅛-inch rings. A mandoline makes this quick.
Dip the slices in the lemon water to stop browning, then pat dry.
Lay them in a single layer in the air basket (and on a rack over the June pan if you need more room). Dust with cinnamon if you like.
Oven: Dehydrate 135°F, 6 to 8 hours, until leathery with no moisture when you tear one
Cool completely, then store airtight.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'dehydrate, snack, kids', 'https://juneoven.com/pages/recipe-dried-apple-rings-7797fe72', 'https://recipe-media.juneoven.com/recipes-prod/rec_7797fe72-3680-41e6-b1a6-cce2b0a1eb4c.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Dried Apple Rings","summary":"Chewy dried apple rings with the Dehydrate mode.","category":"Snacks & dips","mode":"Dehydrate","temp":"135°F","shelf":"Middle","prep":"15 min","cook":"6–8 hr","servings":"About 40 rings","ingredients":"3 apples\n1 cup water mixed with 2 Tbsp lemon juice\nGround cinnamon (optional)","steps":"Core the apples and slice them crosswise into ⅛-inch rings. A mandoline makes this quick.\nDip the slices in the lemon water to stop browning, then pat dry.\nLay them in a single layer in the air basket (and on a rack over the June pan if you need more room). Dust with cinnamon if you like.\nOven: Dehydrate 135°F, 6 to 8 hours, until leathery with no moisture when you tear one\nCool completely, then store airtight.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"dehydrate, snack, kids"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'dried-apple-rings';
