INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Elotes","summary":"","category":"Snacks & dips","mode":"","temp":"","shelf":"","prep":"","cook":"","servings":"","ingredients":"","steps":"","notes":"","tags":""}', 'Project July', 'Page for a recipe from June''s library', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'elotes';
INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('everything-bagel-breakfast-casserole', 'Everything Bagel Breakfast Casserole', 'Toasted everything bagels soaked overnight in a cheesy custard, with sausage and cream cheese on top. Make it the night before, bake it in the morning.', 'Breakfast', 'Bake', '375°F, then 350°F', 'Middle', '25 min + 4 hr chilling', '1 hr 2 min', '12', '6 everything bagels
2 Tbsp extra-virgin olive oil
8 eggs
1½ cups whole milk
½ cup heavy cream
3 Tbsp chopped green onions
2 tsp onion powder
1½ tsp kosher salt
1 tsp garlic powder
½ tsp black pepper
½ tsp cayenne pepper (optional)
2 cups grated cheddar
1 lb loose breakfast sausage
8 oz cream cheese, cold
1 Tbsp everything bagel seasoning
1 Tbsp chopped chives, to finish', 'Oven: preheat on Bake, 375°F, middle shelf
Tear or cut the bagels into bite-size pieces, about 1 inch. Toss them in a big bowl with the olive oil.
Spread the pieces over the June pan in an even layer so they toast evenly.
Oven: Bake 12 minutes, until lightly toasted
Meanwhile, whisk the eggs, milk and cream in the same bowl until completely smooth. Whisk in the green onions, onion powder, salt, garlic powder, pepper and cayenne, then stir in the cheddar.
Grease a 9×13 baking dish.
Let the toasted bagels cool for 5 minutes. Whisk the egg mixture again, fold in the bagels and let them soak for 5 minutes, stirring gently every minute or so.
Pour everything into the dish. Pinch the sausage into small pieces and scatter them over the top.
Tear the cold cream cheese into small pieces and tuck them into the gaps between the sausage. Sprinkle with the bagel seasoning.
Cover and refrigerate for at least 4 hours, or overnight (up to 16 hours).
Oven: preheat on Bake, 350°F, middle shelf, then Bake 50 minutes, until the center is set and the sausage is cooked through
Rest for 5 minutes, scatter the chives over and serve.', 'Check that your 9×13 dish fits your June before you start; a slightly smaller dish works too, just bake a little longer.

Kept from an owner''s notes of the June app version, rewritten for the wiki.', 'make ahead, holiday, brunch, sausage', '', '', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'starter', 1, '');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Everything Bagel Breakfast Casserole","summary":"Toasted everything bagels soaked overnight in a cheesy custard, with sausage and cream cheese on top. Make it the night before, bake it in the morning.","category":"Breakfast","mode":"Bake","temp":"375°F, then 350°F","shelf":"Middle","prep":"25 min + 4 hr chilling","cook":"1 hr 2 min","servings":"12","ingredients":"6 everything bagels\n2 Tbsp extra-virgin olive oil\n8 eggs\n1½ cups whole milk\n½ cup heavy cream\n3 Tbsp chopped green onions\n2 tsp onion powder\n1½ tsp kosher salt\n1 tsp garlic powder\n½ tsp black pepper\n½ tsp cayenne pepper (optional)\n2 cups grated cheddar\n1 lb loose breakfast sausage\n8 oz cream cheese, cold\n1 Tbsp everything bagel seasoning\n1 Tbsp chopped chives, to finish","steps":"Oven: preheat on Bake, 375°F, middle shelf\nTear or cut the bagels into bite-size pieces, about 1 inch. Toss them in a big bowl with the olive oil.\nSpread the pieces over the June pan in an even layer so they toast evenly.\nOven: Bake 12 minutes, until lightly toasted\nMeanwhile, whisk the eggs, milk and cream in the same bowl until completely smooth. Whisk in the green onions, onion powder, salt, garlic powder, pepper and cayenne, then stir in the cheddar.\nGrease a 9×13 baking dish.\nLet the toasted bagels cool for 5 minutes. Whisk the egg mixture again, fold in the bagels and let them soak for 5 minutes, stirring gently every minute or so.\nPour everything into the dish. Pinch the sausage into small pieces and scatter them over the top.\nTear the cold cream cheese into small pieces and tuck them into the gaps between the sausage. Sprinkle with the bagel seasoning.\nCover and refrigerate for at least 4 hours, or overnight (up to 16 hours).\nOven: preheat on Bake, 350°F, middle shelf, then Bake 50 minutes, until the center is set and the sausage is cooked through\nRest for 5 minutes, scatter the chives over and serve.","notes":"Check that your 9×13 dish fits your June before you start; a slightly smaller dish works too, just bake a little longer.\n\nKept from an owner''s notes of the June app version, rewritten for the wiki.","tags":"make ahead, holiday, brunch, sausage"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'everything-bagel-breakfast-casserole';
