INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('focaccia', 'Focaccia', 'Olive-oily, dimpled focaccia, risen in the oven on Proof.', 'Bread, pizza & sandwiches', 'Bake', '425°F', 'Middle', '20 min + 2 hr rising', '20–25 min', '8', '3 cups (375 g) bread flour or all-purpose flour
2 tsp instant yeast
2 tsp kosher salt
1⅓ cups (320 ml) warm water
5 Tbsp olive oil, divided
Flaky salt and rosemary for the top', 'Stir the flour, yeast and salt together, add the water and 1 Tbsp oil and mix into a shaggy, sticky dough. No kneading needed.
Cover the bowl.
Oven: Proof about 1 hour, until doubled
Pour 3 Tbsp oil into the June pan or a 9×13 pan. Turn the dough into it and gently stretch it toward the corners. If it springs back, wait 10 minutes and stretch again.
Oven: Proof 30 to 45 minutes more, until puffy
Take the pan out of the oven.
Oven: preheat on Bake, 425°F, middle shelf
Drizzle the last 1 Tbsp oil over the dough, press deep dimples all over with oiled fingers, and sprinkle with flaky salt and rosemary.
Oven: Bake 20 to 25 minutes, until deep golden
Cool for 10 minutes in the pan, then move to a rack.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'bread, proof', 'https://juneoven.com/pages/recipe-focaccia-54407483', 'https://recipe-media.juneoven.com/recipes-prod/rec_54407483-a367-4771-9f2c-d7d5d0de832a.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Focaccia","summary":"Olive-oily, dimpled focaccia, risen in the oven on Proof.","category":"Bread, pizza & sandwiches","mode":"Bake","temp":"425°F","shelf":"Middle","prep":"20 min + 2 hr rising","cook":"20–25 min","servings":"8","ingredients":"3 cups (375 g) bread flour or all-purpose flour\n2 tsp instant yeast\n2 tsp kosher salt\n1⅓ cups (320 ml) warm water\n5 Tbsp olive oil, divided\nFlaky salt and rosemary for the top","steps":"Stir the flour, yeast and salt together, add the water and 1 Tbsp oil and mix into a shaggy, sticky dough. No kneading needed.\nCover the bowl.\nOven: Proof about 1 hour, until doubled\nPour 3 Tbsp oil into the June pan or a 9×13 pan. Turn the dough into it and gently stretch it toward the corners. If it springs back, wait 10 minutes and stretch again.\nOven: Proof 30 to 45 minutes more, until puffy\nTake the pan out of the oven.\nOven: preheat on Bake, 425°F, middle shelf\nDrizzle the last 1 Tbsp oil over the dough, press deep dimples all over with oiled fingers, and sprinkle with flaky salt and rosemary.\nOven: Bake 20 to 25 minutes, until deep golden\nCool for 10 minutes in the pan, then move to a rack.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"bread, proof"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'focaccia';
