INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('fudgy-chocolate-chip-brownies', 'Fudgy Chocolate Chip Brownies', 'Dense, fudgy brownies with a crackly top, from one bowl.', 'Desserts & baking', 'Bake', '350°F', 'Middle', '15 min', '25–30 min', '16 squares', '½ cup (1 stick) butter
1 cup sugar
⅓ cup cocoa powder
2 eggs
1 tsp vanilla extract
½ cup flour
¼ tsp kosher salt
¼ tsp baking powder
¾ cup chocolate chips', 'Oven: preheat on Bake, 350°F, middle shelf
Line an 8×8 pan with parchment, leaving some hanging over the sides.
Melt the butter in a big bowl. Whisk in the sugar and cocoa, then the eggs and vanilla, until glossy.
Stir in the flour, salt and baking powder until just combined, then the chocolate chips. Spread in the pan.
Oven: Bake 25 to 30 minutes, until a toothpick comes out with moist crumbs
Cool completely in the pan before lifting out and cutting.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'one bowl, chocolate', 'https://juneoven.com/pages/recipe-fudgy-chocolate-chip-brownies-14d8f8e6', 'https://recipe-media.juneoven.com/recipes-prod/rec_14d8f8e6-e8b7-4304-96b7-8bd58fd0f0a4.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Fudgy Chocolate Chip Brownies","summary":"Dense, fudgy brownies with a crackly top, from one bowl.","category":"Desserts & baking","mode":"Bake","temp":"350°F","shelf":"Middle","prep":"15 min","cook":"25–30 min","servings":"16 squares","ingredients":"½ cup (1 stick) butter\n1 cup sugar\n⅓ cup cocoa powder\n2 eggs\n1 tsp vanilla extract\n½ cup flour\n¼ tsp kosher salt\n¼ tsp baking powder\n¾ cup chocolate chips","steps":"Oven: preheat on Bake, 350°F, middle shelf\nLine an 8×8 pan with parchment, leaving some hanging over the sides.\nMelt the butter in a big bowl. Whisk in the sugar and cocoa, then the eggs and vanilla, until glossy.\nStir in the flour, salt and baking powder until just combined, then the chocolate chips. Spread in the pan.\nOven: Bake 25 to 30 minutes, until a toothpick comes out with moist crumbs\nCool completely in the pan before lifting out and cutting.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"one bowl, chocolate"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'fudgy-chocolate-chip-brownies';
INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('garlic-bread', 'Garlic Bread', 'Soft inside, crisp and golden on top.', 'Bread, pizza & sandwiches', 'Bake', '400°F, then Broil', 'Middle', '10 min', '10–12 min', '6', '1 loaf Italian bread or baguette
6 Tbsp butter, softened
3 garlic cloves, finely grated
2 Tbsp chopped parsley
¼ tsp kosher salt
¼ cup grated Parmesan (optional)', 'Oven: preheat on Bake, 400°F, middle shelf
Mash the butter with the garlic, parsley and salt.
Split the loaf lengthwise and spread the butter over the cut sides. Sprinkle with Parmesan if using.
Set cut side up on the June pan.
Oven: Bake 8 to 10 minutes, until the butter has melted in
Oven: switch to Broil for 1 to 2 minutes, watching closely, until golden at the edges', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'side, quick, popular', 'https://juneoven.com/pages/recipe-garlic-bread-a2d80c0a', 'https://recipe-media.juneoven.com/recipes-prod/rec_a2d80c0a-2f53-43d4-b96e-f81a7305dfb1.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Garlic Bread","summary":"Soft inside, crisp and golden on top.","category":"Bread, pizza & sandwiches","mode":"Bake","temp":"400°F, then Broil","shelf":"Middle","prep":"10 min","cook":"10–12 min","servings":"6","ingredients":"1 loaf Italian bread or baguette\n6 Tbsp butter, softened\n3 garlic cloves, finely grated\n2 Tbsp chopped parsley\n¼ tsp kosher salt\n¼ cup grated Parmesan (optional)","steps":"Oven: preheat on Bake, 400°F, middle shelf\nMash the butter with the garlic, parsley and salt.\nSplit the loaf lengthwise and spread the butter over the cut sides. Sprinkle with Parmesan if using.\nSet cut side up on the June pan.\nOven: Bake 8 to 10 minutes, until the butter has melted in\nOven: switch to Broil for 1 to 2 minutes, watching closely, until golden at the edges","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"side, quick, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'garlic-bread';
