INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Grilled Cheese Sandwich","summary":"Golden, buttery grilled cheese in the oven, two or four at a time.","category":"Bread, pizza & sandwiches","mode":"Bake","temp":"450°F","shelf":"Middle","prep":"5 min","cook":"8–10 min","servings":"2","ingredients":"4 slices sandwich bread\n2 Tbsp butter, softened (or mayonnaise)\n4 slices cheddar or American cheese","steps":"Oven: preheat on Bake, 450°F, with the June pan on the middle shelf\nButter one side of each slice. Build two sandwiches with the cheese inside and the buttered sides out.\nLay the sandwiches on the hot pan.\nOven: Bake 4 to 5 minutes, then turn them over and bake 3 to 5 minutes more, until both sides are golden and the cheese has melted","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"quick, kids, lunch, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'grilled-cheese-sandwich';
