INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Hard-Cooked Eggs","summary":"A batch of hard-cooked eggs without a pot of water.","category":"Breakfast","mode":"Bake","temp":"325°F","shelf":"Middle","prep":"1 min","cook":"25–30 min","servings":"6–12 eggs","ingredients":"6–12 eggs, straight from the fridge\nA big bowl of ice water","steps":"Set the eggs in the cups of a muffin tin so they don''t roll.\nOven: Bake 325°F, middle shelf, 25 to 30 minutes (25 for jammy yolks, 30 for fully firm)\nMove the eggs straight into the ice water for 10 minutes. Peel, or keep in the fridge for up to a week.","notes":"The shells can get small brown spots where they touched the tin. That''s harmless.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"meal prep, eggs, basics"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'hard-cooked-eggs';
