1 Tbsp olive oil
½ tsp kosher salt', 'Oven: preheat on Bake, 300°F, middle shelf
Wash and dry the kale completely; wet kale steams instead of crisping.
Massage in the oil and salt and spread the leaves on the June pan without overlapping.
Oven: Bake 15 to 20 minutes, until crisp but still green', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'snack, vegan', 'https://juneoven.com/pages/recipe-kale-chips-25689907', 'https://recipe-media.juneoven.com/recipes-prod/rec_25689907-c0d0-40a3-966e-6a2f751b9a32.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Kale Chips","summary":"Light, crisp kale chips. Low and slow keeps them green.","category":"Snacks & dips","mode":"Bake","temp":"300°F","shelf":"Middle","prep":"10 min","cook":"15–20 min","servings":"2–4","ingredients":"1 bunch curly kale, stems removed, torn into large pieces\n1 Tbsp olive oil\n½ tsp kosher salt","steps":"Oven: preheat on Bake, 300°F, middle shelf\nWash and dry the kale completely; wet kale steams instead of crisping.\nMassage in the oil and salt and spread the leaves on the June pan without overlapping.\nOven: Bake 15 to 20 minutes, until crisp but still green","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"snack, vegan"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'kale-chips';
