INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('lemon-rosemary-chicken-legs-with-potatoes', 'Lemon-Rosemary Chicken Legs with Potatoes', 'A one-pan dinner: chicken legs roast on top of potatoes that soak up the juices.', 'Chicken & turkey', 'Roast', '425°F', 'Middle', '15 min', '40–45 min', '4', '4 chicken leg quarters, or 8 thighs (bone-in, skin-on)
1½ lb small potatoes, halved
3 Tbsp olive oil
1 lemon, zested, then cut into wedges
2 Tbsp chopped rosemary
4 garlic cloves, sliced
2 tsp kosher salt
1 tsp black pepper', 'Oven: preheat on Roast, 425°F, middle shelf
Toss the potatoes with half the oil, half the salt and pepper, and the garlic, and spread them on the June pan.
Rub the chicken with the rest of the oil, the lemon zest, rosemary and the rest of the salt and pepper. Set the pieces skin side up on the potatoes and tuck the lemon wedges around them.
Oven: Roast 40 to 45 minutes, until the skin is crisp and the thickest piece reads 175°F
Squeeze the roasted lemon over everything before serving.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'one pan, weeknight', 'https://juneoven.com/pages/recipe-lemon-rosemary-chicken-legs-with-potatoes-08711b6f', 'https://recipe-media.juneoven.com/recipes-prod/rec_08711b6f-01e7-420f-aea9-9a21dfde2c86.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Lemon-Rosemary Chicken Legs with Potatoes","summary":"A one-pan dinner: chicken legs roast on top of potatoes that soak up the juices.","category":"Chicken & turkey","mode":"Roast","temp":"425°F","shelf":"Middle","prep":"15 min","cook":"40–45 min","servings":"4","ingredients":"4 chicken leg quarters, or 8 thighs (bone-in, skin-on)\n1½ lb small potatoes, halved\n3 Tbsp olive oil\n1 lemon, zested, then cut into wedges\n2 Tbsp chopped rosemary\n4 garlic cloves, sliced\n2 tsp kosher salt\n1 tsp black pepper","steps":"Oven: preheat on Roast, 425°F, middle shelf\nToss the potatoes with half the oil, half the salt and pepper, and the garlic, and spread them on the June pan.\nRub the chicken with the rest of the oil, the lemon zest, rosemary and the rest of the salt and pepper. Set the pieces skin side up on the potatoes and tuck the lemon wedges around them.\nOven: Roast 40 to 45 minutes, until the skin is crisp and the thickest piece reads 175°F\nSqueeze the roasted lemon over everything before serving.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"one pan, weeknight"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'lemon-rosemary-chicken-legs-with-potatoes';
