INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('pepperoni-pizza', 'Pepperoni Pizza', 'A crisp-bottomed pizza from store-bought or homemade dough.', 'Bread, pizza & sandwiches', 'Bake', '450°F', 'Bottom', '15 min', '10–13 min', '2–3', '1 lb pizza dough, at room temperature
Flour or cornmeal for dusting
⅓ cup pizza sauce
6 oz shredded low-moisture mozzarella
2 oz sliced pepperoni
1 Tbsp olive oil
Pinch of dried oregano', 'Oven: preheat on Bake, 450°F, with the June pan (or a pizza stone that fits) on the bottom shelf, for at least 20 minutes
On a floured sheet of parchment, stretch the dough to about 11 inches, or to fit your pan.
Spread the sauce thinly, leaving a border. Add the cheese, then the pepperoni.
Slide the pizza, parchment and all, onto the hot pan.
Oven: Bake 10 to 13 minutes, until the crust is browned and the cheese bubbles
Brush the crust with olive oil, sprinkle with oregano and let it sit for 2 minutes before slicing.', 'If your June has the Pizza mode, try it in place of Bake and add your notes here.

This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'friday night, kids, grill pan, popular', 'https://juneoven.com/pages/recipe-pepperoni-pizza-24e2aa54', 'https://recipe-media.juneoven.com/recipes-prod/rec_24e2aa54-08c8-4776-b0aa-a6f0306bdc23.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Pepperoni Pizza","summary":"A crisp-bottomed pizza from store-bought or homemade dough.","category":"Bread, pizza & sandwiches","mode":"Bake","temp":"450°F","shelf":"Bottom","prep":"15 min","cook":"10–13 min","servings":"2–3","ingredients":"1 lb pizza dough, at room temperature\nFlour or cornmeal for dusting\n⅓ cup pizza sauce\n6 oz shredded low-moisture mozzarella\n2 oz sliced pepperoni\n1 Tbsp olive oil\nPinch of dried oregano","steps":"Oven: preheat on Bake, 450°F, with the June pan (or a pizza stone that fits) on the bottom shelf, for at least 20 minutes\nOn a floured sheet of parchment, stretch the dough to about 11 inches, or to fit your pan.\nSpread the sauce thinly, leaving a border. Add the cheese, then the pepperoni.\nSlide the pizza, parchment and all, onto the hot pan.\nOven: Bake 10 to 13 minutes, until the crust is browned and the cheese bubbles\nBrush the crust with olive oil, sprinkle with oregano and let it sit for 2 minutes before slicing.","notes":"If your June has the Pizza mode, try it in place of Bake and add your notes here.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"friday night, kids, grill pan, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'pepperoni-pizza';
