INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('roasted-broccoli', 'Roasted Broccoli', 'Charred, nutty broccoli in about 15 minutes.', 'Vegetables & sides', 'Roast', '425°F', 'Middle', '5 min', '15–18 min', '4', '1½ lb broccoli, cut into florets
2 Tbsp olive oil
¾ tsp kosher salt
2 garlic cloves, sliced
Lemon wedges and grated Parmesan, to serve', 'Oven: preheat on Roast, 425°F, middle shelf
Toss the broccoli with the oil, salt and garlic and spread it on the June pan.
Oven: Roast 15 to 18 minutes, until tender with charred edges
Finish with a squeeze of lemon and some Parmesan.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'side, vegetables, quick', 'https://juneoven.com/pages/recipe-roasted-broccoli-869be21d', 'https://recipe-media.juneoven.com/recipes-prod/rec_869be21d-8be1-460f-9f5f-0ff2c438c4b0.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Broccoli","summary":"Charred, nutty broccoli in about 15 minutes.","category":"Vegetables & sides","mode":"Roast","temp":"425°F","shelf":"Middle","prep":"5 min","cook":"15–18 min","servings":"4","ingredients":"1½ lb broccoli, cut into florets\n2 Tbsp olive oil\n¾ tsp kosher salt\n2 garlic cloves, sliced\nLemon wedges and grated Parmesan, to serve","steps":"Oven: preheat on Roast, 425°F, middle shelf\nToss the broccoli with the oil, salt and garlic and spread it on the June pan.\nOven: Roast 15 to 18 minutes, until tender with charred edges\nFinish with a squeeze of lemon and some Parmesan.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"side, vegetables, quick"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-broccoli';
