INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('roasted-brussels-sprouts', 'Roasted Brussels Sprouts', 'Crisp, deeply browned sprouts. Cut side down is the secret.', 'Vegetables & sides', 'Roast', '425°F', 'Middle', '10 min', '20–25 min', '4', '1½ lb Brussels sprouts, trimmed and halved
2 Tbsp olive oil
¾ tsp kosher salt
¼ tsp black pepper
1 Tbsp balsamic vinegar or a squeeze of lemon, to finish', 'Oven: preheat on Roast, 425°F, middle shelf
Toss the sprouts with the oil, salt and pepper and spread on the June pan, cut side down.
Oven: Roast 20 to 25 minutes, until well browned underneath and tender
Toss with the vinegar or lemon and serve.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'side, vegetables', 'https://juneoven.com/pages/recipe-roasted-brussels-sprouts-d128b28c', 'https://recipe-media.juneoven.com/recipes-prod/rec_d128b28c-d638-4de0-a6a9-5e2a0b39a497.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Brussels Sprouts","summary":"Crisp, deeply browned sprouts. Cut side down is the secret.","category":"Vegetables & sides","mode":"Roast","temp":"425°F","shelf":"Middle","prep":"10 min","cook":"20–25 min","servings":"4","ingredients":"1½ lb Brussels sprouts, trimmed and halved\n2 Tbsp olive oil\n¾ tsp kosher salt\n¼ tsp black pepper\n1 Tbsp balsamic vinegar or a squeeze of lemon, to finish","steps":"Oven: preheat on Roast, 425°F, middle shelf\nToss the sprouts with the oil, salt and pepper and spread on the June pan, cut side down.\nOven: Roast 20 to 25 minutes, until well browned underneath and tender\nToss with the vinegar or lemon and serve.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"side, vegetables"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-brussels-sprouts';
