INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('roasted-butternut-squash', 'Roasted Butternut Squash', 'Sweet, caramelized squash cubes for a side, a salad or a grain bowl.', 'Vegetables & sides', 'Roast', '400°F', 'Middle', '15 min', '25–30 min', '4', '1 butternut squash (about 2½ lb), peeled, seeded and cut into 1-inch cubes
2 Tbsp olive oil
1 tsp kosher salt
½ tsp black pepper
1 Tbsp maple syrup (optional)', 'Oven: preheat on Roast, 400°F, middle shelf
Toss the squash with the oil, salt and pepper, and spread it out on the June pan with space between the pieces.
Oven: Roast 25 to 30 minutes, turning once, until tender and browned at the edges
Drizzle with maple syrup in the last 5 minutes if you''d like it sweeter.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'side, fall, vegetables', 'https://juneoven.com/pages/recipe-roasted-butternut-squash-e2391d24', 'https://recipe-media.juneoven.com/recipes-prod/rec_e2391d24-f034-4b8e-9168-5adbf0eba81c.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Butternut Squash","summary":"Sweet, caramelized squash cubes for a side, a salad or a grain bowl.","category":"Vegetables & sides","mode":"Roast","temp":"400°F","shelf":"Middle","prep":"15 min","cook":"25–30 min","servings":"4","ingredients":"1 butternut squash (about 2½ lb), peeled, seeded and cut into 1-inch cubes\n2 Tbsp olive oil\n1 tsp kosher salt\n½ tsp black pepper\n1 Tbsp maple syrup (optional)","steps":"Oven: preheat on Roast, 400°F, middle shelf\nToss the squash with the oil, salt and pepper, and spread it out on the June pan with space between the pieces.\nOven: Roast 25 to 30 minutes, turning once, until tender and browned at the edges\nDrizzle with maple syrup in the last 5 minutes if you''d like it sweeter.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"side, fall, vegetables"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-butternut-squash';
