INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Potatoes","summary":"Golden, crunchy-edged potatoes that go with everything.","category":"Vegetables & sides","mode":"Roast","temp":"425°F","shelf":"Middle","prep":"10 min","cook":"35–40 min","servings":"4","ingredients":"2 lb Yukon Gold or red potatoes, cut into 1½-inch chunks\n3 Tbsp olive oil\n1 tsp kosher salt\n½ tsp black pepper\n1 tsp dried rosemary or thyme (optional)","steps":"Oven: preheat on Roast, 425°F, middle shelf\nToss the potatoes with the oil, salt, pepper and herbs, and spread on the June pan with a cut side down.\nOven: Roast 35 to 40 minutes, turning once after 20 minutes, until browned and tender inside","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"side, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-potatoes';
