INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('roasted-salmon', 'Roasted Salmon', 'Quick, plain roast salmon that stays moist. Add a glaze or keep it simple with lemon.', 'Fish & seafood', 'Roast', '400°F', 'Middle', '5 min', '10–14 min', '4', '4 salmon fillets, about 6 oz each, skin on
1 Tbsp olive oil
1 tsp kosher salt
½ tsp black pepper
1 lemon, cut into wedges', 'Oven: preheat on Roast, 400°F, middle shelf
Pat the salmon dry, rub with oil and season with salt and pepper. Set skin side down on the June pan, lined with parchment if you like.
Oven: Roast 10 to 14 minutes, depending on thickness, until it flakes easily (125°F in the thickest part for medium, 145°F for well done)
Serve with lemon wedges.', 'For a quick glaze, brush with 2 Tbsp soy sauce mixed with 1 Tbsp honey and a little grated ginger before roasting.

This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'quick, weeknight, thermometer, popular', 'https://juneoven.com/pages/recipe-roasted-salmon-2febca90', 'https://recipe-media.juneoven.com/recipes-prod/rec_2febca90-cdce-4045-9f64-d9075dfc8ec0.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Salmon","summary":"Quick, plain roast salmon that stays moist. Add a glaze or keep it simple with lemon.","category":"Fish & seafood","mode":"Roast","temp":"400°F","shelf":"Middle","prep":"5 min","cook":"10–14 min","servings":"4","ingredients":"4 salmon fillets, about 6 oz each, skin on\n1 Tbsp olive oil\n1 tsp kosher salt\n½ tsp black pepper\n1 lemon, cut into wedges","steps":"Oven: preheat on Roast, 400°F, middle shelf\nPat the salmon dry, rub with oil and season with salt and pepper. Set skin side down on the June pan, lined with parchment if you like.\nOven: Roast 10 to 14 minutes, depending on thickness, until it flakes easily (125°F in the thickest part for medium, 145°F for well done)\nServe with lemon wedges.","notes":"For a quick glaze, brush with 2 Tbsp soy sauce mixed with 1 Tbsp honey and a little grated ginger before roasting.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"quick, weeknight, thermometer, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-salmon';
