INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('roasted-whole-chicken', 'Roasted Whole Chicken', 'A simple roast chicken with crisp skin. Use the food thermometer and let the oven tell you when it''s done.', 'Chicken & turkey', 'Roast', '425°F', 'Bottom', '15 min', '1 hr–1 hr 15 min', '4', '1 whole chicken, 3½–4½ lb
2 Tbsp olive oil or softened butter
2 tsp kosher salt
1 tsp black pepper
1 lemon, halved
4 garlic cloves, smashed
A few sprigs of thyme or rosemary', 'Take the chicken out of the fridge 30 minutes before cooking and pat it very dry with paper towels, inside and out.
Oven: preheat on Roast, 425°F, bottom shelf
Rub the chicken all over with the oil or butter and season well with salt and pepper. Put the lemon, garlic and herbs inside.
Tie the legs together and tuck the wing tips under. Set the chicken breast side up on the June pan or in a small roasting dish.
Push the food thermometer into the thickest part of the breast, not touching bone.
Oven: Roast until the breast reaches 160°F, about 1 hour to 1 hour 15 minutes
Rest for 15 minutes before carving; it will rise to 165°F as it rests.', 'For extra-crisp skin, salt the chicken the day before and leave it uncovered in the fridge overnight.

This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'thermometer, sunday dinner, popular', 'https://juneoven.com/pages/recipe-roasted-whole-chicken-8f9d8198', 'https://recipe-media.juneoven.com/recipes-prod/rec_8f9d8198-5e9c-4dab-884e-3b5384879c99.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Roasted Whole Chicken","summary":"A simple roast chicken with crisp skin. Use the food thermometer and let the oven tell you when it''s done.","category":"Chicken & turkey","mode":"Roast","temp":"425°F","shelf":"Bottom","prep":"15 min","cook":"1 hr–1 hr 15 min","servings":"4","ingredients":"1 whole chicken, 3½–4½ lb\n2 Tbsp olive oil or softened butter\n2 tsp kosher salt\n1 tsp black pepper\n1 lemon, halved\n4 garlic cloves, smashed\nA few sprigs of thyme or rosemary","steps":"Take the chicken out of the fridge 30 minutes before cooking and pat it very dry with paper towels, inside and out.\nOven: preheat on Roast, 425°F, bottom shelf\nRub the chicken all over with the oil or butter and season well with salt and pepper. Put the lemon, garlic and herbs inside.\nTie the legs together and tuck the wing tips under. Set the chicken breast side up on the June pan or in a small roasting dish.\nPush the food thermometer into the thickest part of the breast, not touching bone.\nOven: Roast until the breast reaches 160°F, about 1 hour to 1 hour 15 minutes\nRest for 15 minutes before carving; it will rise to 165°F as it rests.","notes":"For extra-crisp skin, salt the chicken the day before and leave it uncovered in the fridge overnight.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"thermometer, sunday dinner, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'roasted-whole-chicken';
