INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('salt-and-pepper-chicken-wings', 'Salt and Pepper Chicken Wings', 'Crisp wings with no frying. A little baking powder in the seasoning is the trick.', 'Chicken & turkey', 'Air Fry', '400°F', 'Middle', '10 min', '25–30 min', '2–3', '2 lb chicken wings, split into flats and drumettes
1 Tbsp baking powder (not baking soda)
1½ tsp kosher salt
1½ tsp coarsely ground black pepper
½ tsp garlic powder
Lemon wedges, to serve', 'Pat the wings very dry. Toss them in a bowl with the baking powder, salt, pepper and garlic powder until evenly coated.
Spread the wings in a single layer in the air basket, with a little space between them. Put the June pan, lined with foil, on the bottom shelf to catch drips.
Oven: preheat on Air Fry, 400°F, basket on the middle shelf
Oven: Air Fry 25 to 30 minutes, turning the wings halfway, until deep golden and crisp
Serve hot with lemon wedges.', 'Wings are safe at 165°F, but they get more tender if cooked to 175–190°F.

This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'game day, air basket', 'https://juneoven.com/pages/recipe-salt-and-pepper-chicken-wings-7a272e59', 'https://recipe-media.juneoven.com/recipes-prod/rec_7a272e59-1ca6-4b15-99ab-e4b9102a6eb5.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Salt and Pepper Chicken Wings","summary":"Crisp wings with no frying. A little baking powder in the seasoning is the trick.","category":"Chicken & turkey","mode":"Air Fry","temp":"400°F","shelf":"Middle","prep":"10 min","cook":"25–30 min","servings":"2–3","ingredients":"2 lb chicken wings, split into flats and drumettes\n1 Tbsp baking powder (not baking soda)\n1½ tsp kosher salt\n1½ tsp coarsely ground black pepper\n½ tsp garlic powder\nLemon wedges, to serve","steps":"Pat the wings very dry. Toss them in a bowl with the baking powder, salt, pepper and garlic powder until evenly coated.\nSpread the wings in a single layer in the air basket, with a little space between them. Put the June pan, lined with foil, on the bottom shelf to catch drips.\nOven: preheat on Air Fry, 400°F, basket on the middle shelf\nOven: Air Fry 25 to 30 minutes, turning the wings halfway, until deep golden and crisp\nServe hot with lemon wedges.","notes":"Wings are safe at 165°F, but they get more tender if cooked to 175–190°F.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"game day, air basket"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'salt-and-pepper-chicken-wings';
