INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('slow-cooked-chili', 'Slow-Cooked Chili', 'A hearty beef and bean chili, left to simmer in the oven all afternoon.', 'Beef, pork & lamb', 'Slow Cook', '', 'Bottom', '25 min', '6–8 hr', '6', '1 Tbsp oil
1 onion, chopped
1 bell pepper, chopped
3 garlic cloves, chopped
1½ lb ground beef
3 Tbsp chili powder
2 tsp ground cumin
1 tsp dried oregano
1½ tsp kosher salt
1 can (28 oz) crushed tomatoes
2 cans (15 oz each) kidney or pinto beans, drained
1 cup beef broth
Toppings: shredded cheddar, sour cream, green onions', 'In an oven-safe pot that fits your June with its lid on, cook the onion and pepper in the oil on the stove until soft. Add the garlic, then the beef, and cook until browned.
Stir in the spices and salt for a minute, then the tomatoes, beans and broth. Bring to a simmer and put the lid on.
Oven: Slow Cook, bottom shelf, 6 to 8 hours
Taste and adjust the salt. Serve with the toppings.', 'Measure your pot before you start: it needs to fit on the bottom shelf with the lid on and room to spare above.

This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'slow cook, make ahead, freezer', 'https://juneoven.com/pages/recipe-slow-cooked-chili-2901d487', 'https://recipe-media.juneoven.com/recipes-prod/rec_2901d487-4da5-442a-956d-90b7d91662e1.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Slow-Cooked Chili","summary":"A hearty beef and bean chili, left to simmer in the oven all afternoon.","category":"Beef, pork & lamb","mode":"Slow Cook","temp":"","shelf":"Bottom","prep":"25 min","cook":"6–8 hr","servings":"6","ingredients":"1 Tbsp oil\n1 onion, chopped\n1 bell pepper, chopped\n3 garlic cloves, chopped\n1½ lb ground beef\n3 Tbsp chili powder\n2 tsp ground cumin\n1 tsp dried oregano\n1½ tsp kosher salt\n1 can (28 oz) crushed tomatoes\n2 cans (15 oz each) kidney or pinto beans, drained\n1 cup beef broth\nToppings: shredded cheddar, sour cream, green onions","steps":"In an oven-safe pot that fits your June with its lid on, cook the onion and pepper in the oil on the stove until soft. Add the garlic, then the beef, and cook until browned.\nStir in the spices and salt for a minute, then the tomatoes, beans and broth. Bring to a simmer and put the lid on.\nOven: Slow Cook, bottom shelf, 6 to 8 hours\nTaste and adjust the salt. Serve with the toppings.","notes":"Measure your pot before you start: it needs to fit on the bottom shelf with the lid on and room to spare above.\n\nThis is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"slow cook, make ahead, freezer"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'slow-cooked-chili';
