INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('steak', 'Steak', 'A thick steak under the broiler, cooked to the doneness you like with the food thermometer.', 'Beef, pork & lamb', 'Broil', 'High', 'Top', '5 min + 30 min resting', '10–14 min', '2', '2 steaks (ribeye, strip or sirloin), about 1–1¼ inches thick
1½ tsp kosher salt
1 tsp black pepper
1 Tbsp oil
1 Tbsp butter (optional)', 'Season the steaks with salt and leave them at room temperature for 30 minutes. Pat dry and rub with oil.
Set the steaks on the June pan or a rack set on it. Push the food thermometer into the side of the thickest steak, to the center.
Oven: Broil on high, top shelf, no preheat
Broil until the top is well browned, about 5 to 7 minutes, then turn the steaks over.
Oven: keep broiling until the center reads 125°F for medium-rare (135°F for medium), another 4 to 7 minutes
Top with the butter and rest for 5 minutes before slicing.', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'thermometer, quick, popular', 'https://juneoven.com/pages/recipe-steak-d65db552', 'https://recipe-media.juneoven.com/recipes-prod/rec_d65db552-bf50-4141-b157-e400ba605f28.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Steak","summary":"A thick steak under the broiler, cooked to the doneness you like with the food thermometer.","category":"Beef, pork & lamb","mode":"Broil","temp":"High","shelf":"Top","prep":"5 min + 30 min resting","cook":"10–14 min","servings":"2","ingredients":"2 steaks (ribeye, strip or sirloin), about 1–1¼ inches thick\n1½ tsp kosher salt\n1 tsp black pepper\n1 Tbsp oil\n1 Tbsp butter (optional)","steps":"Season the steaks with salt and leave them at room temperature for 30 minutes. Pat dry and rub with oil.\nSet the steaks on the June pan or a rack set on it. Push the food thermometer into the side of the thickest steak, to the center.\nOven: Broil on high, top shelf, no preheat\nBroil until the top is well browned, about 5 to 7 minutes, then turn the steaks over.\nOven: keep broiling until the center reads 125°F for medium-rare (135°F for medium), another 4 to 7 minutes\nTop with the butter and rest for 5 minutes before slicing.","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"thermometer, quick, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'steak';
