INSERT OR IGNORE INTO recipes (slug, title, summary, category, mode, temp, shelf, prep, cook, servings, ingredients, steps, notes, tags, june_url, image_url, is_stub, rev, created_at, updated_at, origin, featured, image_credit) VALUES ('sunny-side-up-eggs', 'Sunny-Side Up Eggs', 'Set whites and runny yolks, no flipping.', 'Breakfast', 'Bake', '375°F', 'Middle', '2 min', '7–10 min', '1–2', '2–4 eggs
1 tsp butter or oil
Salt and pepper', 'Oven: preheat on Bake, 375°F, middle shelf, with a small oven-safe pan or the egg pan inside
Carefully take out the hot pan, add the butter and swirl to coat.
Crack in the eggs and season with salt and pepper.
Oven: Bake 7 to 10 minutes, until the whites are set and the yolks still jiggle', 'This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.', 'quick, eggs, egg pan, popular', 'https://juneoven.com/pages/recipe-sunny-side-up-eggs-1e631ed9', 'https://recipe-media.juneoven.com/recipes-prod/rec_1e631ed9-1ea3-4dc2-a3d7-fe6f8cefe118.650x433.jpg', 0, 1, '2026-10-11T00:00:00.000Z', '2026-10-11T00:00:00.000Z', 'june', 1, 'June');
INSERT OR IGNORE INTO revisions (recipe_id, rev, data, author, comment, ip_hash, created_at) SELECT id, 1, '{"title":"Sunny-Side Up Eggs","summary":"Set whites and runny yolks, no flipping.","category":"Breakfast","mode":"Bake","temp":"375°F","shelf":"Middle","prep":"2 min","cook":"7–10 min","servings":"1–2","ingredients":"2–4 eggs\n1 tsp butter or oil\nSalt and pepper","steps":"Oven: preheat on Bake, 375°F, middle shelf, with a small oven-safe pan or the egg pan inside\nCarefully take out the hot pan, add the butter and swirl to coat.\nCrack in the eggs and season with salt and pepper.\nOven: Bake 7 to 10 minutes, until the whites are set and the yolks still jiggle","notes":"This is a starter version written for the wiki, not June''s original. If you made June''s version, add its settings and tips here.","tags":"quick, eggs, egg pan, popular"}', 'Project July', 'Starter version written by Project July', '', '2026-10-11T00:00:00.000Z' FROM recipes WHERE slug = 'sunny-side-up-eggs';
